import{_ as o,c as t,o as s,ah as r}from"./chunks/framework.PvdZnrZd.js";const h=JSON.parse('{"title":"Seller URL customisation","description":"Seller URL customisation","frontmatter":{"title":"Seller URL customisation","description":"Seller URL customisation","author":"Chirag Tyagi"},"headers":[],"relativePath":"zenith/seller/seller-URL-customisation.md","filePath":"zenith/seller/seller-URL-customisation.md"}'),n={name:"zenith/seller/seller-URL-customisation.md"};function a(l,e,i,p,u,c){return s(),t("div",null,[...e[0]||(e[0]=[r('<p>In this documentation, we&#39;ll find out how the admin can customize the seller login URL/seller subdomain for <a href="/zenith/introduction/">Multi-Vendor Marketplace App</a> for Shopify.</p><p>Note: During the app Installation and onboarding process. You can now modify the part of your existing(default) Seller URL that appears before &quot;.sp-seller.webkul.com&quot; once</p><p>If you want to customize the entire seller URL, then follow the instructions shared below:</p><h2 id="steps-to-customize-seller-login-url" tabindex="-1">Steps to Customize Seller Login URL: <a class="header-anchor" href="#steps-to-customize-seller-login-url" aria-label="Permalink to &quot;Steps to Customize Seller Login URL:&quot;">​</a></h2><h3 id="in-case-you-are-using-any-other-web-hosting-services-other-than-cloudflare" tabindex="-1">In case you are using any other Web hosting Services other than Cloudflare <a class="header-anchor" href="#in-case-you-are-using-any-other-web-hosting-services-other-than-cloudflare" aria-label="Permalink to &quot;In case you are using any other Web hosting Services other than Cloudflare&quot;">​</a></h3><p>You need to create a CNAME record through your web hosting platform, such as GoDaddy, Shopify, Domain Factory, etc.</p><p>As an example, we will use Shopify here:</p><p>Visit your <strong>Shopify backend</strong> &gt; <strong>Setting</strong> &gt; <strong>Domains</strong>.</p><p>Select the Domain.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2024/10/capture2-1200x472.webp" alt="image"></p><p>Furthermore, you need to click on <strong>Edit</strong> <strong>DNS Setting</strong> from <strong>Domain Setting.</strong></p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2024/10/cap3-1200x575.webp" alt="image"></p><p>Then select <strong>CNAME record</strong> from the drop-down options.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2024/10/cna4.webp" alt="image"></p><p>You need to enter the Name as something like &#39;seller,&#39; &#39;vendor,&#39; or &#39;marketplace,&#39;, etc depending on what you prefer to display.</p><p>For example:</p><p>If you enter &#39;<strong>seller</strong>&#39; as the Host Name, your URL will be: <strong>seller.mystore.com/.</strong><br> If you enter &#39;<strong>vendor</strong>&#39; as the Host Name, your URL will be: <strong>vendor.mystore.com/.</strong></p><p>And Point to: <strong>sh-saas-ssl.webkul.com</strong></p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2024/10/cnam1-1.webp" alt="image"></p><p>Now, once this is done, the URL won’t work instantly. You need to inform us at <a href="mailto:support@webkul.com" target="_blank" rel="noreferrer">support@webkul.com</a>.</p><p>We will make the edits from our end, and then it will start working.</p><h3 id="in-case-you-are-using-cloudflare-as-your-dns" tabindex="-1">In Case you are using Cloudflare as your DNS <a class="header-anchor" href="#in-case-you-are-using-cloudflare-as-your-dns" aria-label="Permalink to &quot;In Case you are using Cloudflare as your DNS&quot;">​</a></h3><p>You need to navigate to the DNS &gt;&gt; Records. Furthermore, Click on the Add Record. As mentioned in the image below.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2024/10/cloud1-1200x471.webp" alt="image"></p><p>Next, enter the required details, such as the <strong>Name</strong>, and set the <strong>Target</strong> to <strong>sh-saas-ssl.webkul.com</strong>. Make sure to <strong>disable the proxy status</strong>, as shown in the image below, and then click <strong>Save</strong>.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2019/11/ssh-1200x602.webp" alt="ssh"></p>',26)])])}const d=o(n,[["render",a]]);export{h as __pageData,d as default};
